-- ── shared ─────────────────────────────────────────────────────────────
-- A setup write's target is refused, before anyone is asked, when the
-- setup guide is off (42501) or an argument is a credential (DKS01) or
-- one the operation does not take (22023).
create or replace function public.mcp_setup_target_guard(p_workspace_id uuid, p_args jsonb, p_allowed text[])
returns void language plpgsql stable security definer set search_path = public as $fn$
begin
  if not public.feature_effective(p_workspace_id, 'setupGuide') then
    raise exception 'the setup guide is off in this workspace' using errcode = '42501';
  end if;
  perform public.mcp_setup_arguments(p_args, p_allowed);
end;
$fn$;
revoke execute on function public.mcp_setup_target_guard(uuid, jsonb, text[]) from public, anon, authenticated;

-- ── explain_setup_step ─────────────────────────────────────────────────
-- One step (or every step, in the guide's order) as the catalogue defines
-- it, with its state and what an assistant may do about it, read from
-- get_setup_status so the two never disagree; `unlocks` are the steps
-- that wait for it. Read only.
create or replace function public.mcp_op_explain_setup_step(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_refusal jsonb := public.mcp_setup_refusal(c.workspace_id, p_args, array['workspace_id', 'step']);
  v_status jsonb;
  v_steps jsonb;
begin
  if v_refusal is not null then return v_refusal; end if;
  if p_args ? 'step' and not exists (select 1 from jsonb_array_elements(public.setup_step_catalogue()) s
                                      where s->>'id' = p_args->>'step') then
    return public.mcp_outcome('validation_error', null, 'invalid_arguments');
  end if;
  v_status := public.mcp_op_get_setup_status(c, jsonb_build_object('workspace_id', c.workspace_id));
  if v_status->>'status' <> 'completed' then return v_status; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'step', s->>'id', 'group', s->>'group', 'milestone', s->>'milestone', 'route', s->>'route',
           'required', (s->>'required')::boolean, 'depends_on', s->'depends_on', 'feature', s->>'feature',
           'actor', s->>'actor', 'estimate_minutes', (s->>'estimate_minutes')::int,
           'takes_credentials', coalesce((s->>'secret')::boolean, false),
           'state', st->>'state', 'reason', st->>'reason', 'blocked_by', st->'blocked_by',
           'manual', (st->>'manual')::boolean, 'assistant', coalesce(st->>'assistant', 'none'),
           'unlocks', (select coalesce(jsonb_agg(d->>'id' order by o), '[]'::jsonb)
                         from jsonb_array_elements(public.setup_step_catalogue()) with ordinality y(d, o)
                        where d->'depends_on' ? (s->>'id'))) order by i), '[]'::jsonb)
    into v_steps
    from jsonb_array_elements(public.setup_step_catalogue()) with ordinality x(s, i)
    left join lateral (select e from jsonb_array_elements(v_status->'data'->'steps') e
                        where e->>'step' = s->>'id' limit 1) t(st) on true
   where not p_args ? 'step' or s->>'id' = p_args->>'step';
  return public.mcp_outcome('completed', jsonb_build_object('steps', v_steps));
end;
$fn$;

-- ── set_opening_hours ──────────────────────────────────────────────────
-- What a change of hours does: each booking rule that differs, from -> to,
-- over the effective values (mcp_booking_period_minutes, the stored open
-- weekdays or the server's default). The result keeps a weekday open and
-- start < boundary < end within the day, as the hours step does.
create or replace function public.setup_hours_plan(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_days jsonb;
  v_now jsonb;
  v_new jsonb;
  v_changes jsonb := '[]'::jsonb;
  k text;
begin
  select jsonb_build_object(
           'open_weekdays', coalesce(w.booking_rules->'open_weekdays', '[1,2,3,4,5]'::jsonb),
           'work_start_minutes', m.work_start, 'half_boundary_minutes', m.half_boundary,
           'work_end_minutes', m.work_end)
    into v_now
    from public.workspaces w, public.mcp_booking_period_minutes(w.id) m
   where w.id = p_workspace_id;
  v_new := v_now;
  if p_args ? 'open_weekdays' then
    if coalesce(p_args->>'open_weekdays', '') !~ '^\s*[1-7](\s*,\s*[1-7])*\s*$' then
      raise exception 'open_weekdays are ISO weekday numbers 1-7 separated by commas' using errcode = '22023';
    end if;
    select jsonb_agg(d order by d) into v_days
      from (select distinct trim(x)::int d from unnest(string_to_array(p_args->>'open_weekdays', ',')) x) y;
    v_new := jsonb_set(v_new, '{open_weekdays}', v_days);
  end if;
  foreach k in array array['work_start_minutes', 'half_boundary_minutes', 'work_end_minutes'] loop
    if p_args ? k then
      v_new := jsonb_set(v_new, array[k], to_jsonb((p_args->>k)::int));
    end if;
  end loop;
  if not ((v_new->>'work_start_minutes')::int >= 0
          and (v_new->>'work_start_minutes')::int < (v_new->>'half_boundary_minutes')::int
          and (v_new->>'half_boundary_minutes')::int < (v_new->>'work_end_minutes')::int
          and (v_new->>'work_end_minutes')::int <= 24 * 60) then
    raise exception 'the working day must run start < half-day boundary < end' using errcode = '22023';
  end if;
  foreach k in array array['open_weekdays', 'work_start_minutes', 'half_boundary_minutes', 'work_end_minutes'] loop
    if v_new->k <> v_now->k then
      v_changes := v_changes || jsonb_build_object('field', k, 'from', v_now->k, 'to', v_new->k);
    end if;
  end loop;
  return jsonb_build_object('changes', v_changes, 'revision', md5(v_now::text));
end;
$fn$;
revoke execute on function public.setup_hours_plan(uuid, jsonb) from public, anon, authenticated;

create or replace function public.mcp_target_set_opening_hours(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v jsonb;
begin
  perform public.mcp_setup_target_guard(p_workspace_id, p_args, array['workspace_id', 'request_id',
    'open_weekdays', 'work_start_minutes', 'half_boundary_minutes', 'work_end_minutes']);
  v := public.setup_hours_plan(p_workspace_id, p_args);
  if v->'changes' = '[]'::jsonb then
    raise exception 'the hours change nothing' using errcode = '22023';
  end if;
  return jsonb_build_object('kind', 'opening_hours', 'changes', v->'changes', 'revision', v->>'revision');
end;
$fn$;
revoke execute on function public.mcp_target_set_opening_hours(uuid, jsonb) from public, anon, authenticated;

-- Runs only after the person confirmed the exact change; each changed
-- rule goes through set_booking_rule, the hours step's own command, which
-- checks workspaceSettings for the person again.
create or replace function public.mcp_op_set_opening_hours(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_refusal jsonb := public.mcp_setup_refusal(c.workspace_id, p_args, array['workspace_id', 'request_id',
    'open_weekdays', 'work_start_minutes', 'half_boundary_minutes', 'work_end_minutes']);
  v jsonb;
  ch jsonb;
begin
  if v_refusal is not null then return v_refusal; end if;
  v := public.setup_hours_plan(c.workspace_id, p_args);
  for ch in select e from jsonb_array_elements(v->'changes') e loop
    perform public.set_booking_rule(c.workspace_id, ch->>'field', ch->'to');
  end loop;
  return public.mcp_outcome('completed', jsonb_build_object('changes', v->'changes'));
end;
$fn$;

-- ── add_closure_days ───────────────────────────────────────────────────
-- The days a request would close: well-formed dates, distinct, in order,
-- without those already closed; the revision is which of them are closed.
create or replace function public.setup_closure_plan(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_days date[];
  v_new jsonb;
  v_closed jsonb;
begin
  if coalesce(p_args->>'days', '') !~ '^\s*\d{4}-\d{2}-\d{2}(\s*,\s*\d{4}-\d{2}-\d{2})*\s*$' then
    raise exception 'days are YYYY-MM-DD dates separated by commas' using errcode = '22023';
  end if;
  begin
    select array_agg(distinct trim(x)::date) into v_days from unnest(string_to_array(p_args->>'days', ',')) x;
  exception when invalid_datetime_format or datetime_field_overflow then
    raise exception 'days are YYYY-MM-DD dates separated by commas' using errcode = '22023';
  end;
  select coalesce(jsonb_agg(to_char(d, 'YYYY-MM-DD') order by d) filter (where cd.id is null), '[]'::jsonb),
         coalesce(jsonb_agg(to_char(d, 'YYYY-MM-DD') order by d) filter (where cd.id is not null), '[]'::jsonb)
    into v_new, v_closed
    from unnest(v_days) d
    left join public.closure_days cd on cd.workspace_id = p_workspace_id and cd.day = d;
  return jsonb_build_object('days', v_new, 'reason', coalesce(p_args->>'reason', ''),
    'revision', md5(v_closed::text));
end;
$fn$;
revoke execute on function public.setup_closure_plan(uuid, jsonb) from public, anon, authenticated;

create or replace function public.mcp_target_add_closure_days(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v jsonb;
begin
  perform public.mcp_setup_target_guard(p_workspace_id, p_args, array['workspace_id', 'request_id', 'days', 'reason']);
  v := public.setup_closure_plan(p_workspace_id, p_args);
  if v->'days' = '[]'::jsonb then
    raise exception 'every one of these days is already closed' using errcode = '22023';
  end if;
  return jsonb_build_object('kind', 'closure_days', 'days', v->'days', 'reason', v->>'reason',
    'revision', v->>'revision');
end;
$fn$;
revoke execute on function public.mcp_target_add_closure_days(uuid, jsonb) from public, anon, authenticated;

-- Runs only after the person confirmed the days. The hours step inserts
-- the rows itself under closure_days' write policy (workspaceSettings);
-- this definer checks the same permission for the person before writing.
create or replace function public.mcp_op_add_closure_days(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_refusal jsonb := public.mcp_setup_refusal(c.workspace_id, p_args, array['workspace_id', 'request_id', 'days', 'reason']);
  v jsonb;
begin
  if v_refusal is not null then return v_refusal; end if;
  if not public.has_permission(c.workspace_id, 'workspaceSettings') then
    return public.mcp_outcome('denied', null, 'forbidden');
  end if;
  v := public.setup_closure_plan(c.workspace_id, p_args);
  insert into public.closure_days (workspace_id, day, reason)
  select c.workspace_id, d::date, v->>'reason' from jsonb_array_elements_text(v->'days') d
  on conflict (workspace_id, day) do nothing;
  return public.mcp_outcome('completed', jsonb_build_object(
    'days', (select coalesce(jsonb_agg(jsonb_build_object('day', d, 'reason', v->>'reason')), '[]'::jsonb)
               from jsonb_array_elements_text(v->'days') d)));
end;
$fn$;

-- ── set_number_sequence ────────────────────────────────────────────────
-- What a change of one series does, over its stored row (or the journal's
-- defaults while nothing is stored), refused as set_number_sequence would
-- refuse it: a restart more often than the printed date, a next number
-- below the current one, the date dropped from a series that issued
-- numbers without a new prefix or suffix.
create or replace function public.setup_numbering_plan(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_seq public.number_sequences;
  v_now jsonb;
  v_new jsonb;
  v_changes jsonb := '[]'::jsonb;
  k text;
begin
  if not (p_args->>'journal' = any (array['invoice', 'credit_note', 'vat_declaration', 'member', 'payment'])) then
    raise exception 'unknown journal' using errcode = '22023';
  end if;
  select * into v_seq from public.number_sequences
   where workspace_id = p_workspace_id and journal = p_args->>'journal';
  if v_seq.journal is null then
    select p_workspace_id, p_args->>'journal', d.prefix, '', d.date_part, 4, d.reset, true, '', 1
      into v_seq.workspace_id, v_seq.journal, v_seq.prefix, v_seq.suffix, v_seq.date_part, v_seq.digits,
           v_seq.reset, v_seq.gapless, v_seq.period_key, v_seq.next_value
      from public.number_sequence_defaults(p_args->>'journal') d;
  end if;
  v_now := jsonb_build_object('prefix', v_seq.prefix, 'suffix', v_seq.suffix, 'date_part', v_seq.date_part,
    'digits', v_seq.digits, 'reset', v_seq.reset, 'next_value', v_seq.next_value);
  v_new := v_now;
  foreach k in array array['prefix', 'suffix', 'date_part', 'digits', 'reset', 'next_value'] loop
    if p_args ? k then v_new := jsonb_set(v_new, array[k], p_args->k); end if;
  end loop;
  if (v_new->>'next_value')::bigint < v_seq.next_value then
    raise exception 'a sequence never goes backwards' using errcode = '22023';
  end if;
  if not public.number_sequence_pair_valid(v_new->>'date_part', v_new->>'reset') then
    raise exception 'a number series cannot restart more often than it prints its date' using errcode = '22023';
  end if;
  if public.number_sequence_date_rank(v_new->>'date_part') < public.number_sequence_date_rank(v_seq.date_part)
     and v_seq.next_value > 1 and v_new->>'prefix' = v_seq.prefix and v_new->>'suffix' = v_seq.suffix then
    raise exception 'removing the date from a series that issued numbers needs a new prefix or suffix'
      using errcode = '22023';
  end if;
  foreach k in array array['prefix', 'suffix', 'date_part', 'digits', 'reset', 'next_value'] loop
    if v_new->k <> v_now->k then
      v_changes := v_changes || jsonb_build_object('field', k, 'from', v_now->k, 'to', v_new->k);
    end if;
  end loop;
  return jsonb_build_object('journal', v_seq.journal, 'changes', v_changes, 'values', v_new,
    'revision', md5(coalesce(to_jsonb(v_seq)::text, '')));
end;
$fn$;
revoke execute on function public.setup_numbering_plan(uuid, jsonb) from public, anon, authenticated;

create or replace function public.mcp_target_set_number_sequence(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v jsonb;
begin
  perform public.mcp_setup_target_guard(p_workspace_id, p_args, array['workspace_id', 'request_id', 'journal',
    'prefix', 'suffix', 'date_part', 'digits', 'reset', 'next_value']);
  v := public.setup_numbering_plan(p_workspace_id, p_args);
  if v->'changes' = '[]'::jsonb then
    raise exception 'the series changes nothing' using errcode = '22023';
  end if;
  return jsonb_build_object('kind', 'number_sequence', 'journal', v->>'journal', 'changes', v->'changes',
    'revision', v->>'revision');
end;
$fn$;
revoke execute on function public.mcp_target_set_number_sequence(uuid, jsonb) from public, anon, authenticated;

-- Runs only after the person confirmed the change, through the editor's
-- own command, which checks manageBilling for the person again. Like the
-- editor it sends every value of the series, so a series stored for the
-- first time is exactly the one the person confirmed.
create or replace function public.mcp_op_set_number_sequence(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_refusal jsonb := public.mcp_setup_refusal(c.workspace_id, p_args, array['workspace_id', 'request_id', 'journal',
    'prefix', 'suffix', 'date_part', 'digits', 'reset', 'next_value']);
  v jsonb;
begin
  if v_refusal is not null then return v_refusal; end if;
  v := public.setup_numbering_plan(c.workspace_id, p_args);
  perform public.set_number_sequence(c.workspace_id, v->>'journal', v->'values'->>'prefix',
    v->'values'->>'suffix', v->'values'->>'date_part', (v->'values'->>'digits')::int,
    v->'values'->>'reset', (v->'values'->>'next_value')::bigint);
  return public.mcp_outcome('completed', jsonb_build_object('journal', v->>'journal', 'changes', v->'changes',
    'preview', public.preview_document_number(c.workspace_id, p_args->>'journal')));
end;
$fn$;

-- Every handler is reached only through mcp_execute_v1.
revoke execute on function public.mcp_op_explain_setup_step(public.mcp_call_context, jsonb) from public, anon, authenticated;
revoke execute on function public.mcp_op_set_opening_hours(public.mcp_call_context, jsonb) from public, anon, authenticated;
revoke execute on function public.mcp_op_add_closure_days(public.mcp_call_context, jsonb) from public, anon, authenticated;
revoke execute on function public.mcp_op_set_number_sequence(public.mcp_call_context, jsonb) from public, anon, authenticated;

notify pgrst, 'reload schema';

select public.set_deskilo_schema_version(9999);
